"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):

    if user_id not in self.users:
        return {"error": f"User {user_id} not found."}

    existing_nums = []
    for rid in self.hotels:
        if rid.startswith("HR-"):
            try:
                existing_nums.append(int(rid.split("-")[1]))
            except ValueError:
                pass
    next_num = max(existing_nums, default=0) + 1
    reservation_id = f"HR-{next_num:04d}"

    reservation = HotelReservation(
        reservation_id=reservation_id,
        user_id=user_id,
        hotel_id=hotel.hotel_id,
        hotel_name=hotel.hotel_name,
        city=hotel.city,
        check_in=hotel.check_in,
        check_out=hotel.check_out,
        room_type=hotel.room_type,
        nightly_rate=hotel.nightly_rate,
        total_price=hotel.total_price,
        status="confirmed",
        booked_at=self.now,
    )
    self.hotels[reservation_id] = reservation

    return {
        "status": "confirmed",
        "reservation_id": reservation_id,
        "hotel_id": hotel.hotel_id,
        "hotel_name": hotel.hotel_name,
        "total_price": hotel.total_price,
        "room_type": hotel.room_type,
    }

def get_hotel_reservation(self, params: dict[str, Any]) -> dict[str, Any]:
    """Look up a hotel reservation by ID."""
    reservation_id = params.get("reservation_id", "")
    hotel = self.hotels.get(reservation_id)
    if not hotel:
        return {"error": f"Hotel reservation {reservation_id} not found."}
    return hotel.to_dict()

def search_car_rentals(self, params: dict[str, Any]) -> dict[str, Any]:
    """Search available car rentals by location, dates, class, and max daily rate."""
    pickup_location = _normalize_city(params.get("pickup_location", "")) if params.get("pickup_location") else ""
    car_class = params.get("car_class")
    max_daily_rate = params.get("max_daily_rate")

    results = []
    pickup_date = params.get("pickup_date")
    dropoff_date = params.get("dropoff_date")

    for c in self.car_inventory.values():
        if pickup_location and c.pickup_location.upper() != pickup_location:
            continue
        if pickup_date and c.pickup_date != pickup_date:
            continue
        if dropoff_date and c.dropoff_date != dropoff_date:
            continue
        if car_class and c.car_class != car_class:
            continue
        if max_daily_rate is not None:
            try:
                rate_limit = int(max_daily_rate)
                if rate_limit >= 0 and c.daily_rate > rate_limit:
                    continue
            except (ValueError, TypeError):
                pass
        results.append(
            {
                "car_id": c.car_id,
                "company": c.company,
                "pickup_location": c.pickup_location,
                "dropoff_location": c.dropoff_location,
                "pickup_date": c.pickup_date,
                "dropoff_date": c.dropoff_date,
                "car_class": c.car_class,

        reservation_id = params.get("reservation_id", "")
        hotel = self.hotels.get(reservation_id)
        if not hotel:
            return {"error": f"Hotel reservation {reservation_id} not found."}
        return hotel.to_dict()

    def search_car_rentals(self, params: dict[str, Any]) -> dict[str, Any]:
        """Search available car rentals by location, dates, class, and max daily rate."""
        pickup_location = _normalize_city(params.get("pickup_location", "")) if params.get("pickup_location") else ""
        car_class = params.get("car_class")
        max_daily_rate = params.get("max_daily_rate")

        results = []
        pickup_date = params.get("pickup_date")
        dropoff_date = params.get("dropoff_date")

        for c in self.car_inventory.values():
            if pickup_location and c.pickup_location.upper() != pickup_location:
                continue
            if pickup_date and c.pickup_date != pickup_date:
                continue
            if dropoff_date and c.dropoff_date != dropoff_date:
                continue
            if car_class and c.car_class != car_class:
                continue
            if max_daily_rate is not None:
                try:
                    rate_limit = int(max_daily_rate)
                    if rate_limit >= 0 and c.daily_rate > rate_limit:
                        continue
                except (ValueError, TypeError):
                    pass
            results.append(
                {
                    "car_id": c.car_id,
                    "company": c.company,
                    "pickup_location": c.pickup_location,
                    "dropoff_location": c.dropoff_location,
                    "pickup_date": c.pickup_date,
                    "dropoff_date": c.dropoff_date,
                    "car_class": c.car_class,
                    "daily_rate": c.daily_rate,
                    "total_price": c.total_price,
                    "insurance_included": c.insurance_included,
                }
            )

        if not results:
            return {"car_rentals": [], "message": "No car rentals found matching your criteria."}
        return {"car_rentals": results[:10]}

    def get_car_rental(self, params: dict[str, Any]) -> dict[str, Any]:
        """Look up a car rental by ID."""
        rental_id = params.get("rental_id", "")
        car = self.car_rentals.get(rental_id)
        if not car:
            return {"error": f"Car rental {rental_id} not found."}
        return car.to_dict()

    @property
    def tool_handlers(self) -> dict[str, Any]:
        return {
            "search_flights": self.search_flights,
            "get_user_details": self.get_user_details,
            "get_user_reservations": self.get_user_reservations,
            "get_booking": self.get_booking,
            "get_policies": self.get_policies,
            "create_booking": self.create_booking,
            "search_hotels": self.search_hotels,
            "book_hotel": self.book_hotel,
            "get_hotel_reservation": self.get_hotel_reservation,
            "search_car_rentals": self.search_car_rentals,
            "get_car_rental": self.get_car_rental,
        }


